dataTableFormat:
{
  "is multi section": "true",
  "sections": [
    {
      "section id": "gtex_de_tissue",
      "header": "Differential Expression by Tissue",
      "data point": {
        "type": "bioindex",
        "url": "https://cfde.hugeampkpnbi.org/api/bio/query/diff-exp-tissue?q=$tissue&limit=10000",
        "continue url": "https://cfde.hugeampkpnbi.org/api/bio/cont?limit=10000&token=",
        "parameters": [
          "tissue"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "search parameters": [
        {
          "parameter": "tissue",
          "label": "Tissue",
          "type": "list",
          "values": [
            {
              "label": "Adipose tissue",
              "value": "adipose_tissue"
            },
            {
              "label": "Adrenal tissue",
              "value": "adrenal_tissue"
            },
            {
              "label": "Blood",
              "value": "blood"
            },
            {
              "label": "Cardiovascular system",
              "value": "cardiovascular_system"
            },
            {
              "label": "Central nervous system",
              "value": "central_nervous_system"
            },
            {
              "label": "Colon",
              "value": "colon"
            },
            {
              "label": "Connective tissue",
              "value": "connective_tissue"
            },
            {
              "label": "Esophagus",
              "value": "esophagus"
            },
            {
              "label": "Female gonad",
              "value": "female_gonad"
            },
            {
              "label": "Gland",
              "value": "gland"
            },
            {
              "label": "Kidney",
              "value": "kidney"
            },
            {
              "label": "Liver",
              "value": "liver"
            },
            {
              "label": "Lung",
              "value": "lung"
            },
            {
              "label": "Mammary gland",
              "value": "mammary_gland"
            },
            {
              "label": "Muscle structure",
              "value": "muscle_structure"
            },
            {
              "label": "Pancreas",
              "value": "pancreas"
            },
            {
              "label": "Prostate gland",
              "value": "prostate_gland"
            },
            {
              "label": "Skin of body",
              "value": "skin_of_body"
            },
            {
              "label": "Small intestine",
              "value": "small_intestine"
            },
            {
              "label": "Spleen",
              "value": "spleen"
            },
            {
              "label": "Stomach",
              "value": "stomach"
            },
            {
              "label": "Testis",
              "value": "testis"
            },
            {
              "label": "Thyroid gland",
              "value": "thyroid_gland"
            },
            {
              "label": "Uterus",
              "value": "uterus"
            },
            {
              "label": "Vagina",
              "value": "vagina"
            }
          ]
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene set",
            "raw field": "gene_set_file"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "geneName"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Mean Expression",
            "raw field": "meanExpression"
          },
          {
            "type": "raw",
            "field name": "Fold Change (log2)",
            "raw field": "log2FoldChange"
          },
          {
            "type": "raw",
            "field name": "Fold Change (log2 SE)",
            "raw field": "log2FoldChangeSE"
          },
          {
            "type": "raw",
            "field name": "Adj. pValue",
            "raw field": "adjustedPValue"
          },
          {
            "type": "raw",
            "field name": "Ensembl ID",
            "raw field": "ensemblID"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "geneName"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype_name"
          },
          {
            "type": "raw",
            "field name": "Phenotype ID",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Statistic",
            "raw field": "Statistic"
          },
          {
            "type": "raw",
            "field name": "pValue",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "calculation type": "-log10",
            "field name": "Adj. pValue (-log10)",
            "raw field": "adjustedPValue"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          },
          {
            "type": "replace characters",
            "field name": "Biosample",
            "raw field": "biosample",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          }
        ],
        "top rows": [
          "Gene",
          "Biosample",
          "Phenotype",
          "Phenotype ID",
          "Mean Expression",
          "Adj. pValue",
          "Fold Change (log2)",
          "Source",
          "Gene set"
        ],
 "tool tips":{
          "Phenotype ID":"Phenotypes are annotated using the Mondo ontology. Note that some phenotypes currently have internal IDs and are not yet mapped to ontology terms.",
          "Mean Expression":"The average expression (in transcripts per million, TPM) of the gene across all samples for this tissue in the analysis. In the plot above, larger dots indicate higher mean expression.",
          "Adj. pValue":"The FDR-corrected p-value indicating the significance of difference between expression values between samples with and without the phenotype. Adjusted p-values (-log10) >1.3 (horizontal dotted line in the plot) are considered statistically significant. In the plot above, dots are colored green or red if they have significant adjusted p-values.",
          "Fold Change (log2)":"A measure of the difference in expression values between samples with and without the phenotype. Values are on a log scale, implying that values >0 indicate increased expression for samples with the phenotype while values <0 indicate decreased expression for samples with the phenotype. Fold change values (log2) >0.5 or <-0.5 (vertical dotted line) are considered to be large, although significance is determined by p-values rather than fold change.",
          "Source":"Source of differential expression data",
          "Gene set":"The gene set in the KC differential expression analysis that this result is a part of. If the gene set has no associations with any phenotype in the KC gene set workflow, no gene set is shown."
        },
        "column formatting": {
          "Gene set": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_gene_set_browser_gene_set?geneSet=",
            "new tab": "true"
          },
          "Gene": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_dge_gene?gene=",
            "new tab": "true"
          },
          "Phenotype ID": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_dge_phenotype?phenotype=",
            "new tab": "true"
          },
          "Mean Expression": {
            "type": [
              "scientific notation"
            ]
          },
          "Adj. pValue": {
            "type": [
              "scientific notation"
            ]
          },
          "Adj. pValue (-log10)": {
            "type": [
              "scientific notation"
            ]
          },
          "Fold Change (log2)": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Gene",
          "label": "Gene",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Phenotype",
          "label": "Phenotype",
          "type": "checkbox"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox"
        }
      ],
      "visualizer": {
        "type": "volcano plot",
        "label": "Differentially Expressed Genes by Tissue",
        "legend": "Legend",
        "render by": "Gene",
        "on hover": [
          "Gene",
          "Biosample",
          "Phenotype",
          "Adj. pValue (-log10)",
          "Fold Change (log2)",
          "Mean Expression"
        ],
        "x axis field": "Fold Change (log2)",
        "x axis label": "Fold Change (log2)",
        "y axis field": "Adj. pValue (-log10)",
        "y axis label": "Adjusted pValue (-log10)",
        "dot scale": "Mean Expression",
        "width": 800,
        "height": 400,
        "x condition": {
          "combination": "or",
          "greater than": 2,
          "lower than": -2
        },
        "y condition": {
          "combination": "greater than",
          "greater than": 2
        }
      }
    }
  ]
}

pageStyle:
.text-align-center{
   text-align:center;
}
.fixed-header {
 position: relative !important;
}
.multi-section-card {
margin-bottom: 20px;
}
#rp_tabs_contents { 
/* background: none !important;
  border: none; */ }

#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
    width: 830px !important;
    margin-left: 0 !important;
}

.byor-single-search-results-wrapper {
    width: 830px !important;
margin-left: 0 !important;
}

span.Tclin > strong {
padding: 0 10px;
    border: solid 2px #337ab7;
    border-radius: 5px;
}
span.Tchem > strong {
padding: 0 10px;
    border: solid 2px #5bc0de;
    border-radius: 5px;
}
span.Tbio > strong {
padding: 0 10px;
    border: solid 2px #ffb259;
    border-radius: 5px;
}
span.Tdark > strong {
padding: 0 10px;
    border: solid 2px #d32f2f;
    border-radius: 5px;
}

.info-card-row {
    margin-bottom: 15px;
}

.info-card-row > .row-key {
    width: 150px; display: inline-block; vertical-align: top;
}

.info-card-row > .row-value {
    width: calc(100% - 150px);  display: inline-block;
}

#byor_single_search { border-color: #ff7f00; }

.volcano-plot-content {
text-align: center;
}


.multi-page-search-wrapper { /*display: none;*/}

.multi-page-search-wrapper.in-section-ui { display: block;}



/* alex css begin */

.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.context-btns-wrapper {
  display: flex;
  gap: 10px;
}
.context-btns-wrapper .btn {
  text-wrap: nowrap;
  background: white;
  color: black;
  border: 1px solid #ccc;
}
.context-btns-wrapper .btn.active {
  background: #ff802c !important;
  border: 1px solid #ccc !important;
}
.context-btns-wrapper .btn.btn-warning {
  background: #ccc;
}
.context-btns-wrapper .btn.btn-warning:hover {
  background: #bbb;
}

.dataset-page-header {
  background: none;
  border: 0;
  display: none;
}

.kp-tabs-contents:has(.multi-page-search-wrapper) {
  /* background: none;
  border: none; */
}

.col-md-12:has(.multi-page-search-wrapper) {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.col-md-12{
  height: fit-content;
}

.tab-ui-wrapper {
  margin: 0;
  background: none;
  border-bottom: 0;
  padding: 0;
}
.tab-content-group {
  background: white;
  border-radius: 0 10px 10px 10px;
  border: 1px solid #ddd;
  padding: 10px 20px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
}

button.show-hide-section, button.capture-data {
  display: none;
}

.tab-content-group:has(.multi-section) {
  padding: 10px 0;
}

.multi-section {
  background: white;
  padding: 10px 20px 30px 20px;
  border-radius: 10px;
  border-bottom: 0;
}

.multi-section .section-header {
  padding: 10px 5px;
}
.multi-section .section-header h4 {
  font-size: 22px;
}
.section-header h4 small {
  font-size: 22px !important;
  padding-left: 10px;
    border-left: solid 1px #dddddd;
    margin-left: 5px;
}

.table-total-rows {
  padding-top: 3px;
}
.table-ui-wrapper {
  display: flex;
  align-items: baseline;
  gap: 5px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
  color: #5a5a5a;
  background: #ddd;
}
.tab-ui-wrapper .tab-ui-tab:hover {
  color: black;
}
.table-ui-wrapper .number-per-page {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}
.convert-2-csv {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}

/* tables */
.mbm-plot-content {
  margin: 0 0 20px 0;
}
.research-data-table-wrapper {
  margin: 0 15px;
}
table.research-data-table {
  border: 0 !important;
  text-align: left;
}
.research-data-table tbody:nth-child(odd) {
  background: #f9f9f9;
}

#section_IDG_gene .research-data-table td {
  border: 0 !important;
  padding: 10px 10px;
  vertical-align: top !important;
}

#section_IDG_gene .egl-table-page-ui-wrapper, #section_IDG_gene .table-total-rows, #section_IDG_gene .table-ui-wrapper {
  display: none;
}

#section_IDG_gene .table-wrapper { margin-top: 25px; }

th.Visit.Pharos { width: 120px !important; }

.research-data-table td {
  border: 0 !important;
  padding: 3px 10px;
  line-height: 1.5em;
}
.research-data-table > thead > tr > th {
  border: 0 !important;
  padding: 5px 10px;
}
.research-data-table > thead > tr > th.sortable-th {
  color: black;
}
[class*="cell-weight"] {
  padding-left: 10px;
}
.sortable-th:after {
  content: '';
  background: none;
  width: 10px;
  height: 10px;
  position: absolute;
  margin: 0 0 0 5px;
  bottom: 7px;
  border-right: 5px solid transparent;
  border-left: 5px solid transparent;
  border-top: 5px solid #b4b4b4;
  border-bottom: 5px solid transparent;
}
table.feature-table {
  border-bottom: 3px solid #cccccc;
}
.feature-table > tr > th.feature-title-th {
  background-color: #cccccc !important;
}
table.feature-table tr:nth-child(odd) {
  background: white;
}
table.feature-table th.feature-th-0 {
  background-color: #eeeeee !important;
  border-left: 0 !important;
  padding: 0.3rem 10px;
  border-bottom: 1px solid #ccc !important;
}

#section_general_gene_info_function .row-value.Function {
  font-size: 16px;
  line-height: 26px;
}

/* colors */  
table a {
  color: #ff6600 !important;
}
.show-evidence-btn {
  background: #ffa02c !important;
  border: 0;
}
.show-evidence-btn:hover {
  background: #dc5800 !important;
  color:white !important;
}
.tab-ui-wrapper .tab-ui-tab.loading > .flag {
  color: #ffaa2c;
}
.page-item.active .page-link {
  background-color: #ffa02c;
}
.page-link {
  color: #ff6600;
}

img.dcc-logo {
  width: 100px;
  height: 100px;
  object-fit: contain;
  margin-top: -15px;
}

/* page descriptions */
.page-description-content {
  /* padding-left: 175px; */
  margin: 10px;
  min-height: 70px;
}
.page-description-content h4 {
  font-size: 16px;
  font-weight: bold;
}
.page-description-content p {
  font-size: 14px;
  line-height: normal;
  margin: 0;
  margin-bottom: 8px;
}

/* filters, search blocks */
.multi-page-search-wrapper {
  height: fit-content;
}
div.filtering-ui-wrapper {
  border: 0;
  border-radius: 0;
  border-left: 3px solid #ff6600;
  margin: 0;
}
.filtering-ui-wrapper>h4.card-title {
  color: #ff6600;
}
.filtering-ui-wrapper.search-criteria {
  /*border: 0;
  background: #efefef;*/
  border-left: 3px solid #34679a;
}
.filtering-ui-wrapper.search-criteria>h4.card-title {
  color: #34679a;
}
.search-fields-wrapper .search-field:empty {
  display: none;
}
.filtering-ui-content .btn-primary {
  background: #ff7f00;
  border: 1px solid transparent;
}
.filtering-ui-content .btn-primary:hover {
  background: #dc5800;
}
.filtering-ui-content .btn-warning {
  background: #ccc;
  border: 1px solid transparent;
}
.filtering-ui-content .btn-primary:hover {
  background: #bbb;
}

.research-data-table td {
overflow-wrap: anywhere;
}

/*center search bar with wrapper*/
.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
